/* ---------- LE CHAMP DE DUNES (asset du propriétaire) ----------
   Miroir du lac, de l'autre côté de la carte. À la différence du lac, ce
   n'est qu'une COUCHE VISUELLE : les cases restent du sable ordinaire, donc
   on construit dessus normalement (le moteur d'empreintes s'y applique). */
const DUNE = { ok: false, mips: {}, hw: 0.879, w: 2.27 };
(function () {
  const img = new Image();
  img.onload = () => { DUNE.img = img; DUNE.ok = true; };
  img.src = "data:image/webp;base64,";
})();
const DUNE_CELLS = [[1, 5], [2, 5], [3, 5], [1, 6], [2, 6], [3, 6], [2, 7], [3, 7]];
const duneSet = new Set(DUNE_CELLS.map((c) => c[0] + "," + c[1]));
const DUNE_CX = DUNE_CELLS.reduce((a, c) => a + c[0], 0) / DUNE_CELLS.length;
const DUNE_CY = DUNE_CELLS.reduce((a, c) => a + c[1], 0) / DUNE_CELLS.length;
function duneImg() {
  const px = DUNE.w * TILE.world * cam.z * DPR;
  const w = [256, 512, DUNE.img.width].find((v) => v >= px) || DUNE.img.width;
  let c = DUNE.mips[w];
  if (!c) {
    c = DUNE.mips[w] = document.createElement("canvas");
    c.width = w; c.height = Math.round(w * DUNE.img.height / DUNE.img.width);
    c.getContext("2d").drawImage(DUNE.img, 0, 0, c.width, c.height);
  }
  return c;
}
